<?php
// Exportación XLSX sin dependencias externas. Texto siempre literal (sin fórmulas).
class ReporteExcel
{
    private static function xml($s){return htmlspecialchars(preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/u','',(string)$s),ENT_XML1|ENT_QUOTES,'UTF-8');}
    private static function columna($n){$r='';do{$r=chr(65+$n%26).$r;$n=(int)floor($n/26)-1;}while($n>=0);return $r;}
    public static function descargar(array $r){
        $f=$r['filtros'];$s=$r['resumen'];$sheets=array();
        $sheets['Resumen']=array(array('Reporte de ventas','PuntoVenta'),array('Desde',$f['desde']),array('Hasta',$f['hasta']),array('Zona horaria','America/Mexico_City'),array('Alcance',$r['todos']?'Administrador: filtros seleccionados':'Solo operaciones propias'),array('Cajero ID',$f['usuario_id']===null?'Todos':(string)$f['usuario_id']),array('Caja ID',$f['caja_id']===null?'Todas':(string)$f['caja_id']),array('Criterio','Ventas y reembolsos por la fecha, caja y usuario que registró cada operación.'),array('Utilidad','Estimada sin impuestos; costo histórico. No incluye gastos ni mermas.'),array('Productos','Los 30 productos con mayor importe neto del periodo.'),array('Concepto','Importe'));
        foreach(array('tickets'=>'Tickets vendidos','reembolsos'=>'Reembolsos registrados','ventas'=>'Venta original','devuelto'=>'Reembolsado','neto'=>'Venta neta con impuestos','sin_impuestos'=>'Venta neta sin impuestos','impuestos'=>'Impuestos netos','costo'=>'Costo neto histórico','utilidad'=>'Utilidad estimada','gastos'=>'Gastos registrados','resultado_despues_gastos'=>'Utilidad menos gastos') as $key=>$label)$sheets['Resumen'][]=array($label,array('n'=>$s[$key]));
        foreach(array('dias'=>array('Por día',array('dia'=>'Día')),'cajeros'=>array('Por cajero',array('cajero_id'=>'ID','nombre'=>'Cajero')),'cajas'=>array('Por caja',array('caja_id'=>'ID','nombre'=>'Caja'))) as $key=>$cfg){$cols=$cfg[1]+array('tickets'=>'Tickets','reembolsos'=>'Reembolsos','ventas'=>'Ventas','devuelto'=>'Reembolsado','neto'=>'Neto','sin_impuestos'=>'Sin impuestos','impuestos'=>'Impuestos','costo'=>'Costo','utilidad'=>'Utilidad estimada');$rows=array(array_values($cols));foreach($r[$key] as $row){$values=array();foreach($cols as $k=>$label)$values[]=in_array($k,array('dia','nombre','cajero_id','caja_id'),true)?$row[$k]:array('n'=>$row[$k]);$rows[]=$values;}$sheets[$cfg[0]]=$rows;}
        foreach(array('gastos'=>array('Gastos registrados',array('categoria'=>'Categoría','origen'=>'Origen','registros'=>'Registros','total'=>'Total pagado')),'pagos_proveedores'=>array('Pagos proveedores',array('origen'=>'Origen','tipo'=>'Método','recibos'=>'Comprobantes','pagado'=>'Pagado')),'abonos'=>array('Abonos recibidos',array('tipo'=>'Método','recibos'=>'Recibos','cobrado'=>'Cobrado')),'pagos'=>array('Métodos de pago',array('tipo_metodo'=>'Tipo','cobrado'=>'Cobrado','devuelto'=>'Reembolsado','neto'=>'Neto')),'productos'=>array('Top 30 productos',array('variante_id'=>'ID variante','nombre'=>'Producto','unidad'=>'Unidad','vendidas'=>'Cantidad vendida','devueltas'=>'Cantidad devuelta','cantidad_neta'=>'Cantidad neta','neto'=>'Importe neto')),'movimientos'=>array('Movimientos',array('folio'=>'Folio','tipo'=>'Tipo','fecha'=>'Fecha CDMX','cajero'=>'Cajero','caja'=>'Caja','total'=>'Importe firmado','subtotal'=>'Sin impuestos','impuestos'=>'Impuestos','costo'=>'Costo histórico','utilidad'=>'Utilidad estimada'))) as $key=>$cfg){$rows=array(array_values($cfg[1]));foreach($r[$key] as $row){$values=array();foreach($cfg[1] as $k=>$label)$values[]=in_array($k,array('registros','pagado','recibos','cobrado','devuelto','neto','vendidas','devueltas','cantidad_neta','total','subtotal','impuestos','costo','utilidad'),true)?array('n'=>$row[$k]):$row[$k];$rows[]=$values;}$sheets[$cfg[0]]=$rows;}
        $path=tempnam(sys_get_temp_dir(),'pos_reporte_');$zip=new ZipArchive();try{
            if($zip->open($path,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('No se pudo generar el archivo.');
            $types='<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>';
            $workbook='<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>';$rels='<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">';$i=0;
            foreach($sheets as $name=>$rows){$i++;$types.='<Override PartName="/xl/worksheets/sheet'.$i.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';$workbook.='<sheet name="'.self::xml($name).'" sheetId="'.$i.'" r:id="rId'.$i.'"/>';$rels.='<Relationship Id="rId'.$i.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$i.'.xml"/>';
                $xml='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="26" customWidth="1"/><col min="2" max="12" width="23" customWidth="1"/></cols><sheetData>';
                foreach($rows as $j=>$cells){$xml.='<row r="'.($j+1).'">';foreach($cells as $col=>$value){$ref=self::columna($col).($j+1);$n=is_array($value)?$value['n']:null;if($n!==null&&preg_match('/^-?[0-9]+(?:\.[0-9]+)?$/D',(string)$n)&&strlen(preg_replace('/[^0-9]/','',ltrim((string)$n,'0')))<=15){$style=strpos((string)$n,'.')!==false?(strlen(substr(strrchr((string)$n,'.'),1))>2?3:2):0;$xml.='<c r="'.$ref.'" s="'.$style.'"><v>'.self::xml($n).'</v></c>';}else{$text=$n!==null?$n:$value;$xml.='<c r="'.$ref.'" t="inlineStr" s="'.($j===0?1:0).'"><is><t xml:space="preserve">'.self::xml($text).'</t></is></c>';}}$xml.='</row>';}$xml.='</sheetData></worksheet>';$zip->addFromString('xl/worksheets/sheet'.$i.'.xml',$xml);
            }
            $zip->addFromString('[Content_Types].xml',$types.'</Types>');$zip->addFromString('xl/workbook.xml',$workbook.'</sheets></workbook>');$zip->addFromString('xl/_rels/workbook.xml.rels',$rels.'<Relationship Id="styles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');$zip->addFromString('_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
            $zip->addFromString('xl/styles.xml','<?xml version="1.0" encoding="UTF-8"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><numFmts count="2"><numFmt numFmtId="164" formatCode="#,##0.00;[Red]-#,##0.00"/><numFmt numFmtId="165" formatCode="#,##0.0000;[Red]-#,##0.0000"/></numFmts><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF165B45"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="4"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFill="1" applyFont="1"/><xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="165" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
            $zip->close();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="ventas-'.$f['desde'].'-a-'.$f['hasta'].'.xlsx"');header('Content-Length: '.filesize($path));readfile($path);
        }finally{if(is_file($path))unlink($path);}exit;
    }
}
